<!doctype html>
<html><head><meta charset="utf-8"><title><?php echo e(__('Purchase Order')); ?> <?php echo e($purchaseOrder->po_number); ?></title><style>body{font-family:Arial;margin:40px;color:#222}.header{display:flex;justify-content:space-between;border-bottom:2px solid #222;padding-bottom:20px}.meta{margin:24px 0}.meta div{margin-bottom:6px}table{width:100%;border-collapse:collapse;margin-top:24px}th,td{border:1px solid #ccc;padding:10px;text-align:left}th{background:#f5f5f5}.total{text-align:right;font-size:18px;font-weight:bold;margin-top:20px}@media print{button{display:none}}</style></head><body><button onclick="window.print()"><?php echo e(__('Print')); ?></button><div class="header"><div><h1><?php echo e(__('Purchase Order')); ?></h1><p><?php echo e($purchaseOrder->po_number); ?></p></div><div><?php echo e($purchaseOrder->order_date?->format('d M Y')); ?></div></div><div class="meta"><div><strong><?php echo e(__('Supplier')); ?>:</strong> <?php echo e($purchaseOrder->supplier?->company_name); ?></div><div><strong><?php echo e(__('Expected Date')); ?>:</strong> <?php echo e($purchaseOrder->expected_date?->format('d M Y') ?: '-'); ?></div><div><strong><?php echo e(__('Payment Terms')); ?>:</strong> <?php echo e($purchaseOrder->supplier?->payment_terms ?: '-'); ?></div></div><table><thead><tr><th><?php echo e(__('Material')); ?></th><th><?php echo e(__('Quantity')); ?></th><th><?php echo e(__('Unit Rate')); ?></th><th><?php echo e(__('Line Total')); ?></th></tr></thead><tbody><?php $__empty_1 = true; $__currentLoopData = $purchaseOrder->items; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $item): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><tr><td><?php echo e($item->material?->item_code); ?> - <?php echo e($item->material?->item_name); ?></td><td><?php echo e($item->quantity); ?></td><td><?php echo e(number_format((float)$item->unit_rate,2)); ?></td><td><?php echo e(number_format((float)$item->line_total,2)); ?></td></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><tr><td colspan="4"><?php echo e(__('No line items')); ?></td></tr><?php endif; ?></tbody></table><div class="total"><?php echo e(__('Total')); ?>: <?php echo e(number_format((float)$purchaseOrder->total_amount,2)); ?></div></body></html>
